    "lumiereTextOnlyHint": "仅显示歌词文字：只画歌词和字上的点亮、光晕、闪点等效果，光源、烟雾、星空、线稿、浮尘、背景歌词、主题图标与画框都不画。字的明暗仍随（不可见的）光束变化。",
    "lumiereTrails": "所有换位都走轨迹线",
