    "lumiereSeamlessTransitions": "轨迹过渡",
    "lumiereSeamlessTransitionsHint": "轨迹过渡：段落之间也像段内换镜头一样在同一束光里交接（光束摆到新角度、线稿擦除重描、字沿轨迹飞到新位置），不再熄灯、闪白或交叉渐变。「所有换位都走轨迹线」让字在每次换行时都沿曲线飞行；是否显示轨迹线由「隐藏轨迹线」决定。",
    "lumiereThemeColorMix": "主题色占比",
