        "sourceTab": "本地、Navidrome 或在线来源的歌曲才有这一页，标签上写的是本地、Navidrome 或歌词；没有来源信息时只有四个标签。",
        "sourceInfo": "最底下是这首歌的来历：本地歌曲是文件名、大小和码率，Navidrome 是 Song ID；在线歌曲没有这一块。",
